<?php
namespace go\modules\legacy\dav;

use GO\Dav\Fs\RootDirectory;
use GO\Dav\Fs\SharedDirectory;
use PHPUnit\Framework\TestCase;
use Sabre\DAV\Exception\Forbidden;

/**
 * The root of the WebDAV files and the "Shared" folder are generated by Group-Office. Renaming them with a WebDAV MOVE
 * would rename a folder on disk, for the root the whole file storage folder.
 */
class RootDirectoryTest extends TestCase
{
	private string $fileStoragePath;
	private string $scratch;

	protected function setUp(): void
	{
		// The root uses the file storage path. Point it to a scratch folder so a rename can't move the real one.
		$this->fileStoragePath = \GO::config()->file_storage_path;
		$this->scratch = \GO::config()->getTempFolder()->path() . '/' . uniqid('davroot') . '/';
		mkdir($this->scratch . 'storage', 0777, true);
		\GO::config()->file_storage_path = $this->scratch . 'storage/';
	}

	protected function tearDown(): void
	{
		\GO::config()->file_storage_path = $this->fileStoragePath;
		foreach (glob($this->scratch . '*') as $dir) {
			rmdir($dir);
		}
		rmdir($this->scratch);
	}

	public function testRootCannotBeRenamed(): void
	{
		try {
			(new RootDirectory())->setName('renamed');
			$this->fail('The root was renamed');
		} catch (Forbidden $e) {
			$this->assertDirectoryExists($this->scratch . 'storage');
			$this->assertDirectoryDoesNotExist($this->scratch . 'renamed');
		}
	}

	public function testSharedCannotBeRenamed(): void
	{
		$this->expectException(Forbidden::class);
		(new SharedDirectory())->setName('renamed');
	}
}
